//! Logic gates (manual 4.14): American, European and IEEE ports, each a node shape, and their
//! variants by their inputs and leads (`number inputs=3`, `no input leads`…), named
//! `american and port|number inputs=3`; the European symbols (`&`, `≥1`, `=1`) are the glyphs'
//! outlines.
//!
//! Measured on what CircuiTikZ 1.8.7 draws (`tools/oracle/`), at the default size, in
//! `bipoles/length`; the text goes at the `text` anchor and does not count in the picture's size.

// measured numbers, some of which happen to be close to constants like 2/π
